#!/usr/bin/env bash
# Generates click-tools/scripts/fase1-spike/test.png — a small 400x300 PNG
# (white border + orange->blue gradient) with zero dependencies beyond the
# `base64` binary that ships with macOS. No ImageMagick/PIL/etc required.
set -euo pipefail

DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
OUT="$DIR/test.png"

base64 -D -o "$OUT" <<'B64' 2>/dev/null || base64 -d -o "$OUT" <<'B64'

B64

echo "[Click Tools] test.png created at: $OUT"
ls -la "$OUT"
